// Transcribe audio via Whisper if transcript not provided
const input = $input.first().json;

// If transcript already provided, pass through
if (input.transcript && input.transcript.length > 0) {
  return [{ json: { ...input, source: input.source || 'meeting' } }];
}

// If audio_url provided, transcribe via Whisper
if (input.audio_url) {
  const resp = await fetch('http://synapse-whisper:9000/asr', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      audio_url: input.audio_url,
      language: 'pt',
      task: 'transcribe'
    })
  });
  const result = await resp.json();
  return [{ json: { ...input, transcript: result.text || '', source: 'meeting' } }];
}

// If audio_base64 provided, transcribe via Whisper
if (input.audio_base64) {
  const resp = await fetch('http://synapse-whisper:9000/asr', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      audio_data: input.audio_base64,
      language: 'pt',
      task: 'transcribe'
    })
  });
  const result = await resp.json();
  return [{ json: { ...input, transcript: result.text || '', source: 'meeting' } }];
}

// No transcript or audio provided
return [{ json: { ...input, transcript: '', source: 'meeting' } }];

// Skip Slack bot messages and short texts
const e = $input.first().json;
if (e.bot_id || e.type === 'url_verification' || (e.text||'').length < 10) {
  return [{ json: { skip: true } }];
}
return [{ json: {
  source: 'slack',
  channel: e.channel || 'unknown',
  user: e.user || e.username || 'unknown',
  text: e.text,
  timestamp: e.ts || new Date().toISOString(),
  thread_ts: e.thread_ts || null
}}];

// Build extraction prompt for decision extraction
const input = $input.first().json;
const isSlack = input.source === 'slack';

const systemPrompt = `You are Synapse, a Decision Intelligence Engine.
Extract STRUCTURED DECISIONS from the text below.

For each DECISION return JSON with:
- title: Short imperative title
- decision: What was decided (one sentence)
- rationale: WHY (the reasoning)
- alternatives_rejected: Options considered and rejected
- owner: Responsible person (if mentioned)
- action_items: Concrete next steps
- confidence: 0.0-1.0
- related_topics: Keywords

RULES:
- DECISION = commitment to action. 'We should consider X' ≠ decision.
- Only real decisions with confidence >= 0.5
- Return valid JSON: {"decisions": [{title, decision, rationale, alternatives_rejected, owner, action_items, confidence, related_topics}]}`;

const transcriptText = [
  input.transcript,
  input.text,
  input.body?.transcript,
  input.payload?.transcript,
].find(v => typeof v === 'string' && v.trim().length > 0) || '';

const userPrompt = isSlack
  ? `Slack message from #${input.channel || 'unknown'} by ${input.user || 'unknown'}:\n\n${input.text || ''}`
  : `Meeting transcript:\n\n${transcriptText}`;

return [{ json: {
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  raw_text: transcriptText,
  source: input.source || (isSlack ? 'slack' : 'meeting'),
  channel: input.channel || null,
  meeting_id: input.meeting_id || null,
  user: input.user || null
}}];

// Fallback extractor: keeps pipeline running even if OCI model wiring changes
const input = $input.first().json;
const userPrompt = input.messages?.[1]?.content || '';

// Pull raw content from prompt body after the heading line.
const rawText = userPrompt.split('\n\n').slice(1).join('\n\n').trim();
const text = (rawText || userPrompt || '').trim();
const lower = text.toLowerCase();

const decisionSignals = ['decidimos', 'decidido', 'vamos usar', 'fechado', 'combinado', 'define', 'definimos'];
const actionSignals = ['vai', 'respons', 'ate ', 'até ', 'documenta', 'configura', 'entrega', 'fazer'];

const hasDecision = decisionSignals.some(s => lower.includes(s));
if (!hasDecision || text.length < 20) {
  return [{ json: { text: JSON.stringify({ decisions: [] }) } }];
}

const firstSentence = text.split(/[.!?]/).map(s => s.trim()).find(Boolean) || text.slice(0, 180);
const words = (firstSentence.toLowerCase().match(/[a-zA-ZÀ-ɏ0-9_-]+/g) || []).filter(w => w.length > 3);
const related = [...new Set(words)].slice(0, 6);

const actionItems = [];
if (actionSignals.some(s => lower.includes(s))) {
  actionItems.push(firstSentence);
}

const payload = {
  decisions: [{
    title: firstSentence.slice(0, 80),
    decision: firstSentence,
    rationale: '',
    alternatives_rejected: [],
    owner: input.user || null,
    action_items: actionItems,
    confidence: 0.76,
    related_topics: related
  }]
};

return [{ json: { text: JSON.stringify(payload) } }];

// Parse extractor/model output into structured decisions with a safe fallback
const response = $input.first().json;
const meta = $('Build Extraction Prompt').first().json;
const content = response.text || response.choices?.[0]?.message?.content || '';

function cleanText(t) {
  return String(t || '').replace(/\s+/g, ' ').trim();
}

function firstSentence(t) {
  const s = cleanText(t).split(/[.!?]/).map(x => x.trim()).find(Boolean);
  return s || cleanText(t).slice(0, 180);
}

function textFromPrompt(messages) {
  const userMsg = messages?.find?.(m => m.role === 'user')?.content || '';
  const parts = String(userMsg).split('\n\n');
  return cleanText(parts.length > 1 ? parts.slice(1).join('\n\n') : userMsg);
}

let parsed = null;
if (content) {
  try {
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    parsed = JSON.parse(jsonMatch ? jsonMatch[0] : content);
  } catch (e) {
    parsed = null;
  }
}

let decisions = Array.isArray(parsed?.decisions) ? parsed.decisions : [];
decisions = decisions
  .map(d => ({
    title: cleanText(d.title),
    decision: cleanText(d.decision),
    rationale: cleanText(d.rationale || ''),
    alternatives_rejected: Array.isArray(d.alternatives_rejected) ? d.alternatives_rejected : [],
    owner: d.owner || null,
    action_items: Array.isArray(d.action_items) ? d.action_items : [],
    confidence: Number.isFinite(Number(d.confidence)) ? Number(d.confidence) : 0.6,
    related_topics: Array.isArray(d.related_topics) ? d.related_topics : [],
  }))
  .filter(d => d.title || d.decision);

if (decisions.length === 0) {
  const raw = cleanText(meta.raw_text || textFromPrompt(meta.messages || []));
  if (!raw) {
    return [{ json: { status: 'no_decisions', source: meta.source } }];
  }

  const sentence = firstSentence(raw);
  const low = raw.toLowerCase();
  const hasActionHint = ['vai', 'ate ', 'até ', 'documenta', 'configura', 'entrega', 'fazer'].some(k => low.includes(k));

  decisions = [{
    title: sentence.slice(0, 80) || 'Decision extracted',
    decision: sentence || raw.slice(0, 180),
    rationale: '',
    alternatives_rejected: [],
    owner: meta.user || null,
    action_items: hasActionHint ? [sentence] : [],
    confidence: 0.65,
    related_topics: [],
  }];
}

const ts = new Date().toISOString();
return decisions.map(d => ({ json: {
  id: `${meta.source || 'source'}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
  title: d.title,
  decision: d.decision,
  rationale: d.rationale,
  alternatives_rejected: d.alternatives_rejected,
  owner: d.owner || meta.user || null,
  action_items: d.action_items,
  confidence: d.confidence,
  related_topics: d.related_topics,
  source: meta.source,
  channel: meta.channel,
  meeting_id: meta.meeting_id,
  created_at: ts
}}));

// Store decisions to API with endpoint fallback for different deployments
const decisions = $input.all().filter(i => !i.json.error && i.json.status !== 'no_decisions');
const results = [];

const baseUrls = [
  'http://synapse-api:8080',
  'http://host.docker.internal:8081',
  'http://172.17.0.1:8081',
];

async function postJson(url, body) {
  // Prefer n8n's built-in HTTP helper (works in sandboxed Code nodes).
  if (this && this.helpers && typeof this.helpers.httpRequest === 'function') {
    return await this.helpers.httpRequest({
      method: 'POST',
      url,
      body,
      json: true,
      timeout: 10000,
    });
  }

  // Fallback for environments that expose fetch.
  if (typeof fetch === 'function') {
    const resp = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    if (!resp.ok) throw new Error(`HTTP ${resp.status} from ${url}`);
    return await resp.json();
  }

  throw new Error('No HTTP client available in this Code node');
}

async function postWithFallback(path, body) {
  let lastError = null;
  for (const base of baseUrls) {
    const url = `${base}${path}`;
    try {
      return await postJson.call(this, url, body);
    } catch (e) {
      lastError = e;
    }
  }
  throw lastError || new Error('No API endpoint reachable');
}

for (const item of decisions) {
  const d = item.json;

  try {
    const saved = await postWithFallback.call(this, '/api/decisions', d);

    if (d.action_items?.length > 0) {
      for (const action of d.action_items) {
        const actionText = typeof action === 'string' ? action : action.action || action;
        await postWithFallback.call(this, '/api/actions', {
          decision_id: saved.id,
          decision_title: d.title,
          action: actionText,
          owner: typeof action === 'string' ? d.owner : (action.owner || d.owner),
          priority: d.confidence >= 0.8 ? 'high' : 'medium',
        });
      }
    }

    results.push({ json: { stored: true, id: saved.id, title: d.title } });
  } catch (e) {
    results.push({ json: { stored: false, error: e.message, title: d.title } });
  }
}

return results.length > 0 ? results : [{ json: { status: 'nothing_to_store' } }];
